with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__EMP_CODE))) as HUB_PARTY_HK
        , GRADE_CODE as DESIGNATION_BAND
        , DOJ as DATE_OF_JOINING
        , cast(null as varchar) as EMPLOYEE_ID
        , cast(null as varchar) as MEMBER_NAME
        , cast(null as varchar) as ACTIVE_INDICATOR
        , cast(null as varchar) as LOCATION_REFERENCE
        , 'BGIL_GMC_FINAL_INSTL_DATA' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_bgil_gmc_final_instl_data') }}
    where (nullif(trim(EMP_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__EMP_CODE))) as HUB_PARTY_HK
        , cast(null as varchar) as DESIGNATION_BAND
        , cast(null as varchar) as DATE_OF_JOINING
        , cast(null as varchar) as EMPLOYEE_ID
        , EMP_NEME as MEMBER_NAME
        , cast(null as varchar) as ACTIVE_INDICATOR
        , cast(null as varchar) as LOCATION_REFERENCE
        , 'BJAZ_ECARD_MEMBR_DEL_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ecard_membr_del_dtls') }}
    where (nullif(trim(EMP_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__MEMBER_NO))) as HUB_PARTY_HK
        , cast(null as varchar) as DESIGNATION_BAND
        , cast(null as varchar) as DATE_OF_JOINING
        , EMP_NO as EMPLOYEE_ID
        , cast(null as varchar) as MEMBER_NAME
        , cast(null as varchar) as ACTIVE_INDICATOR
        , cast(null as varchar) as LOCATION_REFERENCE
        , 'BJAZ_HAT_ID_MEM_DETLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_id_mem_detls') }}
    where (nullif(trim(MEMBER_NO),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PART_ID))) as HUB_PARTY_HK
        , cast(null as varchar) as DESIGNATION_BAND
        , cast(null as varchar) as DATE_OF_JOINING
        , cast(null as varchar) as EMPLOYEE_ID
        , cast(null as varchar) as MEMBER_NAME
        , STATUS as ACTIVE_INDICATOR
        , cast(null as varchar) as LOCATION_REFERENCE
        , 'BJAZ_HC_PART_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hc_part_extn') }}
    where (nullif(trim(PART_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__LDR_PID))) as HUB_PARTY_HK
        , cast(null as varchar) as DESIGNATION_BAND
        , cast(null as varchar) as DATE_OF_JOINING
        , EMP_NO as EMPLOYEE_ID
        , cast(null as varchar) as MEMBER_NAME
        , cast(null as varchar) as ACTIVE_INDICATOR
        , cast(null as varchar) as LOCATION_REFERENCE
        , 'BJAZ_HM_COINSU_CLM_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_coinsu_clm_dtls') }}
    where (nullif(trim(LDR_PID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSPITAL_ID))) as HUB_PARTY_HK
        , cast(null as varchar) as DESIGNATION_BAND
        , DOJ as DATE_OF_JOINING
        , cast(null as varchar) as EMPLOYEE_ID
        , cast(null as varchar) as MEMBER_NAME
        , cast(null as varchar) as ACTIVE_INDICATOR
        , cast(null as varchar) as LOCATION_REFERENCE
        , 'BJAZ_HM_HCM_EXTRACT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcm_extract') }}
    where (nullif(trim(HOSPITAL_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__MEMBER_ID))) as HUB_PARTY_HK
        , GRADE as DESIGNATION_BAND
        , cast(null as varchar) as DATE_OF_JOINING
        , CO_EMPNUMBER as EMPLOYEE_ID
        , cast(null as varchar) as MEMBER_NAME
        , cast(null as varchar) as ACTIVE_INDICATOR
        , EMPLOYEE_LOCATION as LOCATION_REFERENCE
        , 'BJAZ_HM_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_dtls') }}
    where (nullif(trim(MEMBER_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PAYER_CODE))) as HUB_PARTY_HK
        , cast(null as varchar) as DESIGNATION_BAND
        , cast(null as varchar) as DATE_OF_JOINING
        , EMPLOYEE_ID as EMPLOYEE_ID
        , cast(null as varchar) as MEMBER_NAME
        , cast(null as varchar) as ACTIVE_INDICATOR
        , cast(null as varchar) as LOCATION_REFERENCE
        , 'BJAZ_REMEDINET_CLAIM_DETAILS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_remedinet_claim_details') }}
    where (nullif(trim(PAYER_CODE),'')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DESIGNATION_BAND end) as DESIGNATION_BAND,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DATE_OF_JOINING end) as DATE_OF_JOINING,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EMPLOYEE_ID end) as EMPLOYEE_ID,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_NAME end) as MEMBER_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ACTIVE_INDICATOR end) as ACTIVE_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LOCATION_REFERENCE end) as LOCATION_REFERENCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when DESIGNATION_BAND is not null or DATE_OF_JOINING is not null or EMPLOYEE_ID is not null or MEMBER_NAME is not null or ACTIVE_INDICATOR is not null or LOCATION_REFERENCE is not null
                     then md5(upper(coalesce(cast(DESIGNATION_BAND as varchar), '') || '|' || coalesce(cast(DATE_OF_JOINING as varchar), '') || '|' || coalesce(cast(EMPLOYEE_ID as varchar), '') || '|' || coalesce(cast(MEMBER_NAME as varchar), '') || '|' || coalesce(cast(ACTIVE_INDICATOR as varchar), '') || '|' || coalesce(cast(LOCATION_REFERENCE as varchar), '')))
                end as SAT_PARTY_GROUP_CENSUS_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_GROUP_CENSUS_HASHDIFF is not null
